// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import {ClankCurveMath} from "./libraries/ClankCurveMath.sol";

/// @title Clank launcher token
/// @notice Burnable ERC-20 deployed for one launch and initially minted completely to its curve.
/// @dev The reference and metadata fields mirror the Pons launcher-token model for indexer
/// compatibility and grant no privileges.
contract ClankLauncherToken is ERC20, ERC20Burnable {
    struct Socials {
        string twitter;
        string telegram;
        string discord;
        string website;
        string farcaster;
    }

    struct Metadata {
        string logo;
        string description;
        Socials socials;
    }

    error InvalidAddress();
    error InvalidSupply();

    address public immutable deployer;
    address public immutable launchFactory;
    address public immutable curve;
    string public logo;
    string public description;

    Socials private _socials;

    constructor(
        string memory name_,
        string memory symbol_,
        Metadata memory metadata_,
        address deployer_,
        address curve_,
        address launchFactory_,
        uint256 supply_
    ) ERC20(name_, symbol_) {
        if (deployer_ == address(0) || curve_ == address(0) || launchFactory_ == address(0)) {
            revert InvalidAddress();
        }
        if (supply_ != ClankCurveMath.TOKEN_SUPPLY) revert InvalidSupply();

        deployer = deployer_;
        launchFactory = launchFactory_;
        curve = curve_;
        logo = metadata_.logo;
        description = metadata_.description;
        _socials = metadata_.socials;
        _mint(curve_, supply_);
    }

    /// @notice Returns the five social metadata fields in the Pons-compatible order.
    function socials()
        external
        view
        returns (
            string memory twitter,
            string memory telegram,
            string memory discord,
            string memory website,
            string memory farcaster
        )
    {
        Socials memory values = _socials;
        return (values.twitter, values.telegram, values.discord, values.website, values.farcaster);
    }

    /// @notice Returns creator and metadata in the Pons-compatible launcher-token tuple.
    function getTokenInfo()
        external
        view
        returns (
            address tokenDeployer,
            string memory tokenLogo,
            string memory tokenDescription,
            Socials memory tokenSocials
        )
    {
        return (deployer, logo, description, _socials);
    }
}

contracts/ClankLaunchDeployer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Create2} from "@openzeppelin/contracts/utils/Create2.sol";

import {ClankBondingCurve} from "./ClankBondingCurve.sol";
import {ClankLauncherToken} from "./ClankLauncherToken.sol";

/// @notice Complete deterministic deployment input for one curve/token pair.
struct ClankLaunchDeployment {
    string name;
    string symbol;
    ClankLauncherToken.Metadata metadata;
    address creator;
    uint256 supply;
    bytes32 launchId;
    ClankBondingCurve.Config curveConfig;
}

/// @title Clank launch deployer
/// @notice Handles CREATE2 deployment and address prediction for launch curve/token pairs.
/// @dev Split from the factory to mirror Pons' contract responsibilities and keep deployment
/// bytecode out of the orchestration surface exposed to integrations.
contract ClankLaunchDeployer {
    error AddressMismatch(address expected, address actual);
    error InvalidAddress();
    error NotFactory();

    address public immutable factory;

    constructor(address factory_) {
        if (factory_ == address(0)) revert InvalidAddress();
        factory = factory_;
    }

    modifier onlyFactory() {
        if (msg.sender != factory) revert NotFactory();
        _;
    }

    function deployLaunch(ClankLaunchDeployment calldata params)
        external
        onlyFactory
        returns (address token, address curve)
    {
        (address predictedToken, address predictedCurve) = predictLaunchAddresses(params);

        curve = address(new ClankBondingCurve{salt: curveSalt(params.launchId)}(params.curveConfig));
        if (curve != predictedCurve) revert AddressMismatch(predictedCurve, curve);

        token = address(
            new ClankLauncherToken{salt: tokenSalt(params.launchId)}(
                params.name, params.symbol, params.metadata, params.creator, curve, factory, params.supply
            )
        );
        if (token != predictedToken) revert AddressMismatch(predictedToken, token);
    }

    function predictLaunchAddresses(ClankLaunchDeployment calldata params)
        public
        view
        returns (address token, address curve)
    {
        bytes32 curveBytecodeHash =
            keccak256(abi.encodePacked(type(ClankBondingCurve).creationCode, abi.encode(params.curveConfig)));
        curve = Create2.computeAddress(curveSalt(params.launchId), curveBytecodeHash, address(this));

        bytes32 tokenBytecodeHash = keccak256(
            abi.encodePacked(
                type(ClankLauncherToken).creationCode,
                abi.encode(params.name, params.symbol, params.metadata, params.creator, curve, factory, params.supply)
            )
        );
        token = Create2.computeAddress(tokenSalt(params.launchId), tokenBytecodeHash, address(this));
    }

    function curveSalt(bytes32 launchId) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(launchId, "CLANK_CURVE"));
    }

    function tokenSalt(bytes32 launchId) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(launchId, "CLANK_TOKEN"));
    }
}

contracts/ClankGraduationGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Pool} from "@uniswap/v4-core/src/libraries/Pool.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {LiquidityAmounts} from "@uniswap/v4-periphery/src/libraries/LiquidityAmounts.sol";

import {ClankMigrationMath} from "./libraries/ClankMigrationMath.sol";
import {ClankCurveMath} from "./libraries/ClankCurveMath.sol";

/// @title Clank graduation preflight
/// @notice Validates that terminal assets produce nonzero full-range liquidity within V4's per-tick limit.
contract ClankGraduationGuard {
    error GraduationSeedNotViable();
    error InvalidAddress();
    error InvalidTickSpacing();
    error SqrtPriceOutOfBounds();

    /// @notice Checks a curve's terminal assets and returns the price used to initialize V4.
    function assertSeedableForCurve(
        address token,
        address pairToken,
        int24 tickSpacing,
        uint256 quoteAmount,
        uint256 tokenAmount,
        uint256 phantomQuote
    ) external pure returns (uint160 price) {
        price = ClankMigrationMath.migrationPrice(token, pairToken, quoteAmount, tokenAmount, phantomQuote);
        _assertSeedableAtPrice(token, pairToken, tickSpacing, quoteAmount, tokenAmount, price);
    }

    function assertSeedable(
        address token,
        address pairToken,
        int24 tickSpacing,
        uint256 quoteAmount,
        uint256 tokenAmount
    ) external pure {
        (uint256 amount0, uint256 amount1) = pairToken < token ? (quoteAmount, tokenAmount) : (tokenAmount, quoteAmount);
        _assertSeedableAtPrice(
            token, pairToken, tickSpacing, quoteAmount, tokenAmount, ClankMigrationMath.sqrtPriceX96(amount0, amount1)
        );
    }

    function _assertSeedableAtPrice(
        address token,
        address pairToken,
        int24 tickSpacing,
        uint256 quoteAmount,
        uint256 tokenAmount,
        uint160 sqrtPriceX96
    ) private pure {
        if (token == address(0)) revert InvalidAddress();
        if (pairToken == token) revert InvalidAddress();
        if (tickSpacing <= 0) revert InvalidTickSpacing();
        if (
            quoteAmount == 0 || tokenAmount == 0 || quoteAmount > ClankCurveMath.MAX_GRADUATION_QUOTE
                || tokenAmount > ClankCurveMath.MAX_GRADUATION_QUOTE
        ) {
            revert GraduationSeedNotViable();
        }

        (uint256 amount0, uint256 amount1) = pairToken < token ? (quoteAmount, tokenAmount) : (tokenAmount, quoteAmount);
        if (sqrtPriceX96 <= TickMath.MIN_SQRT_PRICE || sqrtPriceX96 >= TickMath.MAX_SQRT_PRICE) {
            revert SqrtPriceOutOfBounds();
        }

        int24 tickLower = TickMath.minUsableTick(tickSpacing);
        int24 tickUpper = TickMath.maxUsableTick(tickSpacing);
        uint128 liquidity = LiquidityAmounts.getLiquidityForAmounts(
            sqrtPriceX96,
            TickMath.getSqrtPriceAtTick(tickLower),
            TickMath.getSqrtPriceAtTick(tickUpper),
            amount0,
            amount1
        );
        if (liquidity == 0 || liquidity > Pool.tickSpacingToMaxLiquidityPerTick(tickSpacing)) {
            revert GraduationSeedNotViable();
        }
    }
}

contracts/ClankGraduationExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {StateLibrary} from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolIdLibrary} from "@uniswap/v4-core/src/types/PoolId.sol";
import {IPositionManager} from "@uniswap/v4-periphery/src/interfaces/IPositionManager.sol";
import {Actions} from "@uniswap/v4-periphery/src/libraries/Actions.sol";
import {LiquidityAmounts} from "@uniswap/v4-periphery/src/libraries/LiquidityAmounts.sol";
import {IAllowanceTransfer} from "permit2/src/interfaces/IAllowanceTransfer.sol";

import {ClankFeeEscrow} from "./ClankFeeEscrow.sol";
import {IERC721Owner} from "./ClankLaunchLocker.sol";

/// @title Clank Uniswap V4 graduation executor
/// @notice Mints a full-range native-ETH or ERC-20 quote V4 position directly to the immutable launch locker.
/// @dev This contract isolates V4-specific approval, action encoding, dust accounting, and
/// position ownership checks from launch administration. Only the factory may execute a migration.
contract ClankGraduationExecutor is ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Auditable outcome of a V4 graduation attempt.
    struct Result {
        uint256 positionId;
        uint160 sqrtPriceX96;
        uint128 liquidity;
        uint128 seededQuote;
        uint128 seededToken;
        uint128 quoteDust;
        /// @notice Unused launch tokens permanently transferred to the locker.
        uint128 tokenDust;
    }

    error InvalidAddress();
    error InvalidAmount();
    error InvalidPositionOwner();
    error InvalidSqrtPrice();
    error NoLiquidity();
    error NotFactory();
    error NothingToFlush();
    error UnexpectedNativeSender();

    /// @notice Launch factory authorised to invoke pool creation.
    address public immutable factory;
    /// @notice Uniswap V4 pool registry and accounting manager.
    IPoolManager public immutable poolManager;
    /// @notice Uniswap V4 position NFT manager.
    IPositionManager public immutable positionManager;
    /// @notice Permit2 instance used by PositionManager to pull launched tokens.
    IAllowanceTransfer public immutable permit2;
    /// @notice Initialization-only hook embedded in every graduated PoolKey.
    IHooks public immutable initializationHook;
    /// @notice Permanent recipient of every minted liquidity position.
    address public immutable locker;
    /// @notice Pull-payment escrow receiving migration dust.
    ClankFeeEscrow public immutable feeEscrow;
    /// @notice Beneficiary credited with migration dust and recovered foreign native ETH.
    address public immutable protocolFeeRecipient;
    /// @notice Unflushed ERC-20 quote dust, excluding pre-existing donations.
    mapping(address asset => uint256 amount) public pendingQuoteDust;

    event PoolCreated(
        address indexed token,
        uint256 indexed positionId,
        uint160 sqrtPriceX96,
        uint128 liquidity,
        uint128 seededQuote,
        uint128 seededToken,
        uint128 quoteDust,
        uint128 tokenDust
    );
    event ForeignNativeRecovered(uint256 amount, address indexed escrowBeneficiary);
    event QuoteDustFlushed(address indexed asset, uint256 amount);

    /// @param factory_ Launch factory authorised to call mintFullRangePosition.
    /// @param poolManager_ Uniswap V4 PoolManager.
    /// @param positionManager_ Uniswap V4 PositionManager wired to poolManager_.
    /// @param permit2_ Permit2 contract used by PositionManager.
    /// @param initializationHook_ No-fee hook restricting pool initialization to the factory.
    /// @param locker_ Permanent liquidity-position recipient.
    /// @param feeEscrow_ Native and ERC-20 credit escrow.
    /// @param protocolFeeRecipient_ Beneficiary for migration dust and recovered foreign native ETH.
    constructor(
        address factory_,
        address poolManager_,
        address positionManager_,
        address permit2_,
        address initializationHook_,
        address locker_,
        address feeEscrow_,
        address protocolFeeRecipient_
    ) {
        if (
            factory_ == address(0) || poolManager_ == address(0) || positionManager_ == address(0)
                || permit2_ == address(0) || initializationHook_ == address(0) || locker_ == address(0)
                || feeEscrow_ == address(0) || protocolFeeRecipient_ == address(0)
        ) revert InvalidAddress();

        factory = factory_;
        poolManager = IPoolManager(poolManager_);
        positionManager = IPositionManager(positionManager_);
        permit2 = IAllowanceTransfer(permit2_);
        initializationHook = IHooks(initializationHook_);
        locker = locker_;
        feeEscrow = ClankFeeEscrow(feeEscrow_);
        protocolFeeRecipient = protocolFeeRecipient_;
    }

    /// @notice Accepts native refunds and sweep output only from PositionManager.
    receive() external payable {
        if (msg.sender != address(positionManager)) revert UnexpectedNativeSender();
    }

    /// @notice Permissionlessly transfers accumulated ERC-20 quote dust to the fixed escrow beneficiary.
    /// @dev Failed transfers revert the pending amount and remain retryable after pool creation.
    function flushQuoteDust(address asset) external nonReentrant returns (uint256 amount) {
        amount = pendingQuoteDust[asset];
        if (amount == 0) revert NothingToFlush();
        pendingQuoteDust[asset] = 0;

        IERC20 quoteToken = IERC20(asset);
        quoteToken.forceApprove(address(feeEscrow), amount);
        feeEscrow.creditToken(protocolFeeRecipient, asset, amount);
        quoteToken.forceApprove(address(feeEscrow), 0);

        emit QuoteDustFlushed(asset, amount);
    }

    /// @notice Mints a full-range position into the factory-initialized V4 pool.
    /// @dev Currencies are sorted by address and the PoolKey contains the initialization-only guard.
    /// The executor snapshots its own and PositionManager's pre-existing balances so foreign native
    /// ETH returned by SWEEP is never attributed to the current launch.
    /// Temporary approvals are cleared on success.
    /// @param tokenAddress Launched ERC-20 token.
    /// @param pairToken Quote asset; address(0) represents native ETH.
    /// @param poolFee Static V4 LP fee encoded in the PoolKey.
    /// @param tickSpacing Tick spacing encoded in the PoolKey.
    /// @param quoteAmount Quote asset allocated to the position.
    /// @param tokenAmount Token amount allocated to the position.
    /// @return result Position identifier, price, liquidity, seeded amounts, and rounding dust.
    function mintFullRangePosition(
        address tokenAddress,
        address pairToken,
        uint24 poolFee,
        int24 tickSpacing,
        uint128 quoteAmount,
        uint128 tokenAmount
    ) external payable nonReentrant returns (Result memory result) {
        if (msg.sender != factory) revert NotFactory();
        if (
            tokenAddress == address(0) || pairToken == tokenAddress || quoteAmount == 0 || tokenAmount == 0
                || (pairToken == address(0) ? msg.value != quoteAmount : msg.value != 0)
        ) {
            revert InvalidAmount();
        }

        IERC20 token = IERC20(tokenAddress);
        uint256 tokenBalance = token.balanceOf(address(this));
        if (tokenBalance < tokenAmount) revert InvalidAmount();
        IERC20 quoteToken = IERC20(pairToken);
        uint256 quoteTokenBalance;
        if (pairToken != address(0)) {
            quoteTokenBalance = quoteToken.balanceOf(address(this));
            if (quoteTokenBalance < quoteAmount) revert InvalidAmount();
        }

        // Separate assets supplied for this launch from balances that predate the call.
        uint256 nativeBaseline = address(this).balance - msg.value;
        uint256 tokenBaseline = tokenBalance - tokenAmount;
        uint256 quoteTokenBaseline = pairToken == address(0) ? 0 : quoteTokenBalance - quoteAmount;
        uint256 positionManagerNativeBaseline = address(positionManager).balance;

        bool quoteIsCurrency0 = pairToken < tokenAddress;
        address currency0 = quoteIsCurrency0 ? pairToken : tokenAddress;
        address currency1 = quoteIsCurrency0 ? tokenAddress : pairToken;
        uint128 amount0Max = quoteIsCurrency0 ? quoteAmount : tokenAmount;
        uint128 amount1Max = quoteIsCurrency0 ? tokenAmount : quoteAmount;
        PoolKey memory key = PoolKey({
            currency0: Currency.wrap(currency0),
            currency1: Currency.wrap(currency1),
            fee: poolFee,
            tickSpacing: tickSpacing,
            hooks: initializationHook
        });
        (result.sqrtPriceX96,,,) = StateLibrary.getSlot0(poolManager, PoolIdLibrary.toId(key));
        if (result.sqrtPriceX96 <= TickMath.MIN_SQRT_PRICE || result.sqrtPriceX96 >= TickMath.MAX_SQRT_PRICE) {
            revert InvalidSqrtPrice();
        }

        int24 tickLower = TickMath.minUsableTick(tickSpacing);
        int24 tickUpper = TickMath.maxUsableTick(tickSpacing);
        result.liquidity = LiquidityAmounts.getLiquidityForAmounts(
            result.sqrtPriceX96,
            TickMath.getSqrtPriceAtTick(tickLower),
            TickMath.getSqrtPriceAtTick(tickUpper),
            amount0Max,
            amount1Max
        );
        if (result.liquidity == 0) revert NoLiquidity();

        token.forceApprove(address(permit2), tokenAmount);
        permit2.approve(
            tokenAddress, address(positionManager), uint160(tokenAmount), uint48(block.timestamp + 5 minutes)
        );
        if (pairToken != address(0)) {
            quoteToken.forceApprove(address(permit2), quoteAmount);
            permit2.approve(
                pairToken, address(positionManager), uint160(quoteAmount), uint48(block.timestamp + 5 minutes)
            );
        }

        result.positionId = positionManager.nextTokenId();

        // Mint directly to the locker, settle both currencies, then recover unused native ETH.
        bool hasNative = currency0 == address(0);
        bytes memory actions = hasNative
            ? abi.encodePacked(uint8(Actions.MINT_POSITION), uint8(Actions.SETTLE_PAIR), uint8(Actions.SWEEP))
            : abi.encodePacked(uint8(Actions.MINT_POSITION), uint8(Actions.SETTLE_PAIR));
        bytes[] memory params = new bytes[](hasNative ? 3 : 2);
        params[0] =
            abi.encode(key, tickLower, tickUpper, uint256(result.liquidity), amount0Max, amount1Max, locker, bytes(""));
        params[1] = abi.encode(key.currency0, key.currency1);
        if (hasNative) params[2] = abi.encode(key.currency0, address(this));

        positionManager.modifyLiquidities{value: msg.value}(abi.encode(actions, params), block.timestamp + 5 minutes);
        if (IERC721Owner(address(positionManager)).ownerOf(result.positionId) != locker) {
            revert InvalidPositionOwner();
        }

        permit2.approve(tokenAddress, address(positionManager), 0, 0);
        token.forceApprove(address(permit2), 0);
        if (pairToken != address(0)) {
            permit2.approve(pairToken, address(positionManager), 0, 0);
            quoteToken.forceApprove(address(permit2), 0);
        }

        // PositionManager's SWEEP may include native ETH it held before this launch. Attribute at most
        // its baseline balance to foreign ETH, and only the remainder to this launch's rounding dust.
        uint256 foreignNative;
        uint256 launchQuoteDust;
        if (pairToken == address(0)) {
            uint256 nativeDelta = address(this).balance - nativeBaseline;
            foreignNative = Math.min(positionManagerNativeBaseline, nativeDelta);
            launchQuoteDust = nativeDelta - foreignNative;
        } else {
            uint256 quoteAfter = quoteToken.balanceOf(address(this));
            if (quoteAfter < quoteTokenBaseline) revert InvalidAmount();
            launchQuoteDust = quoteAfter - quoteTokenBaseline;
        }
        if (launchQuoteDust > quoteAmount) revert InvalidAmount();

        uint256 tokenAfter = token.balanceOf(address(this));
        if (tokenAfter < tokenBaseline) revert InvalidAmount();
        uint256 launchTokenDust = tokenAfter - tokenBaseline;
        if (launchTokenDust > tokenAmount) revert InvalidAmount();

        result.quoteDust = uint128(launchQuoteDust);
        result.tokenDust = uint128(launchTokenDust);
        result.seededQuote = quoteAmount - result.quoteDust;
        result.seededToken = tokenAmount - result.tokenDust;

        if (launchTokenDust != 0) token.safeTransfer(locker, launchTokenDust);

        if (launchQuoteDust != 0) {
            if (pairToken == address(0)) {
                feeEscrow.credit{value: launchQuoteDust}(protocolFeeRecipient);
            } else {
                pendingQuoteDust[pairToken] += launchQuoteDust;
            }
        }
        uint256 totalForeignNative = nativeBaseline + foreignNative;
        if (totalForeignNative != 0) {
            feeEscrow.credit{value: totalForeignNative}(protocolFeeRecipient);
            emit ForeignNativeRecovered(totalForeignNative, protocolFeeRecipient);
        }

        emit PoolCreated(
            tokenAddress,
            result.positionId,
            result.sqrtPriceX96,
            result.liquidity,
            result.seededQuote,
            result.seededToken,
            result.quoteDust,
            result.tokenDust
        );
    }
}

contracts/libraries/ClankCurveMath.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title Clank bonding-curve mathematics
/// @notice Contains fee conversions and virtual-reserve XYK quote functions.
/// @dev Rounding deliberately favours protocol solvency: outputs round down while required
/// inputs and fees round up.
library ClankCurveMath {
    error GraduationQuoteTooLarge();

    uint256 internal constant BPS = 10_000;
    uint256 internal constant MAX_GRADUATION_QUOTE = uint256(uint128(type(int128).max));
    uint256 internal constant TOKEN_SUPPLY = 1_000_000_000 ether;
    uint256 internal constant MIGRATION_TOKENS = 220_000_000 ether;
    uint256 internal constant SOLD_TOKENS = TOKEN_SUPPLY - MIGRATION_TOKENS;
    uint256 internal constant ALLOCATION_DIFFERENCE = SOLD_TOKENS - MIGRATION_TOKENS;
    // U = L^2 / (A - L). Round down by less than one token base unit.
    uint256 internal constant VIRTUAL_TOKENS = MIGRATION_TOKENS * MIGRATION_TOKENS / ALLOCATION_DIFFERENCE;
    // Absolute full-range V4 seed boundary for the fixed allocation at tick spacing 1 with the token sorted first.
    // The boundary leaves no rounding headroom: intermediate trades near it may revert when their projected terminal
    // liquidity exceeds V4's per-tick cap. We deliberately retain the theoretical maximum for initial configuration
    // and rely on the curve's per-trade graduation validation to ensure every accepted state remains migratable.
    uint256 internal constant MAX_PHANTOM_QUOTE = 65_662_411_597_810_441_635_668_862_687_492_298_262;

    /// @notice Required net quote threshold for the fixed 780M/220M allocation.
    /// @dev Quote inputs are bounded to uint128 by callers; multiplication cannot overflow.
    function graduationThreshold(uint256 phantomQuote) internal pure returns (uint256) {
        return Math.mulDiv(phantomQuote, ALLOCATION_DIFFERENCE, MIGRATION_TOKENS);
    }

    /// @notice Quote required to sell the allocation in one trade, including integer rounding.
    function minimumTerminalQuote(uint256 phantomQuote) internal pure returns (uint256) {
        return requiredBuyInput(phantomQuote, TOKEN_SUPPLY + VIRTUAL_TOKENS, SOLD_TOKENS);
    }

    /// @notice Rejects trades whose rounded reserves would exceed V4's signed quote limit at graduation.
    function validateGraduationQuote(uint256 realQuote, uint256 realTokens, uint256 phantomQuote)
        internal
        pure
        returns (uint256 terminalQuote)
    {
        terminalQuote = realQuote
            + requiredBuyInput(realQuote + phantomQuote, realTokens + VIRTUAL_TOKENS, realTokens - MIGRATION_TOKENS);
        if (terminalQuote > MAX_GRADUATION_QUOTE) revert GraduationQuoteTooLarge();
    }

    /// @notice Calculates a fee included in a gross amount.
    /// @param grossAmount Total amount including the fee.
    /// @param feeBps Fee rate in basis points.
    /// @return Fee amount rounded up.
    function feeFromGross(uint256 grossAmount, uint256 feeBps) internal pure returns (uint256) {
        return Math.mulDiv(grossAmount, feeBps, BPS, Math.Rounding.Ceil);
    }

    /// @notice Converts a gross amount into the amount available after its included fee.
    /// @param grossAmount Total amount including the fee.
    /// @param feeBps Fee rate in basis points.
    /// @return Net amount rounded down.
    function netFromGross(uint256 grossAmount, uint256 feeBps) internal pure returns (uint256) {
        return Math.mulDiv(grossAmount, BPS - feeBps, BPS);
    }

    /// @notice Calculates the gross amount required to produce an exact net amount.
    /// @param netAmount Amount that must remain after the fee.
    /// @param feeBps Fee rate in basis points.
    /// @return Gross amount rounded up.
    function grossFromNet(uint256 netAmount, uint256 feeBps) internal pure returns (uint256) {
        return Math.mulDiv(netAmount, BPS, BPS - feeBps, Math.Rounding.Ceil);
    }

    /// @notice Quotes token output for a net quote-asset input.
    /// @param effectiveQuote Virtual plus tracked real quote reserve before the trade.
    /// @param tokenReserve Virtual plus tracked real token reserve before the trade.
    /// @param netQuoteIn Quote amount entering the pricing reserve after fees.
    /// @return Token output rounded down.
    function buyOutput(uint256 effectiveQuote, uint256 tokenReserve, uint256 netQuoteIn)
        internal
        pure
        returns (uint256)
    {
        return Math.mulDiv(netQuoteIn, tokenReserve, effectiveQuote + netQuoteIn);
    }

    /// @notice Quotes the net quote input required for an exact token output.
    /// @param effectiveQuote Virtual plus tracked real quote reserve before the trade.
    /// @param tokenReserve Virtual plus tracked real token reserve before the trade.
    /// @param tokensOut Exact token amount requested.
    /// @return Required quote input rounded up.
    function requiredBuyInput(uint256 effectiveQuote, uint256 tokenReserve, uint256 tokensOut)
        internal
        pure
        returns (uint256)
    {
        return Math.mulDiv(effectiveQuote, tokensOut, tokenReserve - tokensOut, Math.Rounding.Ceil);
    }

    /// @notice Quotes gross quote output for a token input.
    /// @param effectiveQuote Virtual plus tracked real quote reserve before the trade.
    /// @param tokenReserve Virtual plus tracked real token reserve before the trade.
    /// @param tokensIn Token amount entering the reserve.
    /// @return Gross quote output rounded down.
    function sellOutput(uint256 effectiveQuote, uint256 tokenReserve, uint256 tokensIn)
        internal
        pure
        returns (uint256)
    {
        return Math.mulDiv(effectiveQuote, tokensIn, tokenReserve + tokensIn);
    }
}

